begin;
select no_plan();
select has_function('private','is_valid_draft_document',array['jsonb'],'private document validator exists');
select has_function('private','check_draft_input',array['jsonb'],'private request validator exists');
select ok(private.is_valid_draft_document(null),'SQL NULL is an incomplete body');
select ok(not private.is_valid_draft_document('null'::jsonb),'JSON null is not a document envelope');
select ok(private.is_valid_draft_document('{"format":"gavel-draft","version":1,"document":{"type":"doc","content":[{"type":"paragraph"}]}}'),'minimal document');
select ok(not private.is_valid_draft_link(null),'NULL link rejected');
select ok(not private.is_valid_draft_link('javascript:alert(1)'),'executable link rejected');
select ok(private.is_valid_draft_link('https://example.test/a'),'HTTPS link accepted');
select throws_ok($$select '{"text":"\u0000"}'::jsonb$$,'22P05',null,'JSONB rejects NUL before the function can run');
select throws_ok($$select '{"text":"\ud800"}'::jsonb$$,'22P02',null,'JSONB rejects lone surrogate before the function can run');
select is(p.provolatile,'i'::"char",p.proname||' immutable') from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private' and p.proname in ('is_valid_draft_link','is_valid_draft_document','check_draft_input','draft_json_keys');
select ok(not p.prosecdef,p.proname||' does not elevate privileges') from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private' and p.proname in ('is_valid_draft_link','is_valid_draft_document','check_draft_input','draft_json_keys');
select ok(not has_function_privilege(role,signature,'EXECUTE'),role||' cannot call '||signature) from unnest(array['anon','authenticated']) role cross join unnest(array['private.is_valid_draft_link(text)','private.is_valid_draft_document(jsonb)','private.check_draft_input(jsonb)','private.draft_json_keys(jsonb,text[],text[])']) signature;
select ok(p.proconfig @> array['search_path=""'],p.proname||' pins empty search path') from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private' and p.proname in ('is_valid_draft_link','is_valid_draft_document','check_draft_input','draft_json_keys');
set local role anon;
select throws_ok($$select private.is_valid_draft_link('https://example.test')$$,'42501',null,'anon execution really denied');
reset role;
set local role authenticated;
select throws_ok($$select private.check_draft_input('{}')$$,'42501',null,'authenticated execution really denied');
reset role;
select ok(not private.is_valid_draft_link('https://xn--bcher-kva.example/a'),'valid punycode host is explicitly deferred');
select ok(not private.is_valid_draft_link('https://news.XN--BCHER-KVA.example./a'),'punycode labels are rejected case-insensitively in any host position');
select ok(private.is_valid_draft_link('https://example.test/bücher/xn--bcher-kva?q=é'),'international path and punycode path text remain allowed');
select * from finish();
rollback;
